mapper.select:
select
DATE (create_time) as create_time,
ROUND(sum(long_time),2) as long_time,
ROUND(sum(diatance),2) as  distance
from running

    
        and create_time > #{beginTime}
    
    
        and create_time < #{endTime}
    
    
        and user_id = #{userId}
    

GROUP BY
DATE(create_time)
ORDER BY
DATE(create_time);
